        _MULTI_QUERY_RECEIPT_MAGIC,
        _encode_u64(_MULTI_QUERY_RECEIPT_VERSION, "version"),
        _encode_blob(encode_signed_json_multi_index(checked.bundle)),

def _check_json_value(value: Any) -> None:
    """Validate a find_json / json_search_receipt scalar query value."""
    if isinstance(value, bool) or isinstance(value, str) or value is None:
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("value must be a finite number")
        return
    raise TypeError("value must be str, int, float, bool or None")


def _check_json_threshold(value: Any) -> None:
    """Validate a find_where numeric-comparison threshold.

    Only a non-boolean ``int`` or a finite ``float`` is accepted: booleans
    are not numbers for this comparison, and a non-finite threshold would
    make the comparison degenerate.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("threshold must be an int or a float")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("threshold must be a finite number")


def _parse_json_pointer(pointer: Any) -> tuple[str, ...]:
    """Parse an RFC 6901 JSON Pointer into its tuple of unescaped tokens.

    The empty string is the root pointer and yields ``()``. A non-``str``
    pointer raises TypeError; a non-empty pointer that does not start with
    ``/`` or a reference token carrying an escape other than ``~0`` /
    ``~1`` raises ValueError.
    """
    if not isinstance(pointer, str):
        raise TypeError("pointer must be a string")
    if pointer == "":
        return ()
    if not pointer.startswith("/"):
        raise ValueError("a non-empty JSON Pointer must start with '/'")
    tokens: list[str] = []
    for raw in pointer.split("/")[1:]:
        if "~" not in raw:
            tokens.append(raw)
            continue
        decoded: list[str] = []
        index = 0
        while index < len(raw):
            char = raw[index]
            if char == "~":
                if index + 1 >= len(raw) or raw[index + 1] not in "01":
                    raise ValueError("JSON Pointer escape must be '~0' or '~1'")
                decoded.append("~" if raw[index + 1] == "0" else "/")
                index += 2
            else:
                decoded.append(char)
                index += 1
        tokens.append("".join(decoded))

    # checks above and unconditionally accepts a structurally valid receipt
    # that lists no failing entry; the fallback keeps report.ok pinned to that
    # verifier. A zero-item receipt never exercises the key.
    if not verify_encrypted_search_receipt(checked, key):
        return SearchHitReport(False, None, _HIT_RECEIPT_CODE_ROOT)
    return SearchHitReport(True, None, None)


def _encode_u64(value: int, name: str) -> bytes:
    if not 0 <= value < _U64_LIMIT:
        raise ValueError(f"{name} must satisfy 0 <= {name} < 2**64")
    return value.to_bytes(_U64_BYTES, "big")


def _encode_blob(material: bytes) -> bytes:
    return _encode_u64(len(material), "blob length") + material


class _CodecReader:
    """Bounds-checked cursor over a canonical auditchain binary encoding.

    Centralizes the input-boundary, integer and byte-blob rules the offline
    credential decoders share, so each format keeps exactly one statement of
    them: the input must be exact ``bytes`` starting with the format magic
    (anything else raises TypeError, a bad magic ValueError), integers are
    unsigned 8-byte big-endian values, and every blob is a u64 byte length
    followed by the raw bytes. Truncation, a declared length beyond the
    remaining input, invalid UTF-8 in ``hash_name``, a version mismatch and
    trailing bytes all raise ValueError.
    """

    """

    __slots__ = ("_data", "_offset", "_kind")

    def __init__(self, data: Any, magic: bytes, kind: str) -> None:
        if not isinstance(data, bytes):
            raise TypeError("data must be bytes")
        if not data.startswith(magic):
            raise ValueError(f"not an auditchain {kind} encoding")
        self._data = data
        self._offset = len(magic)
        self._kind = kind

    def read_u64(self, name: str) -> int:
        end = self._offset + _U64_BYTES
        if end > len(self._data):
            raise ValueError(f"truncated encoding: expected 8 bytes for {name}")
        value = int.from_bytes(self._data[self._offset : end], "big")
        self._offset = end
        return value

    def read_blob(self, name: str) -> bytes:
        length = self.read_u64(f"{name} length")
        end = self._offset + length
        if end > len(self._data):
            raise ValueError(f"truncated encoding: {name} is {length} bytes")
        blob = self._data[self._offset : end]
        self._offset = end
        return blob

    def read_version(self, expected: int) -> None:
        version = self.read_u64("version")
        if version != expected:
            raise ValueError(f"unsupported {self._kind} version")

    def read_text(self, name: str) -> str:
        raw = self.read_blob(name)
        try:
            return raw.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError(f"{name} is not valid UTF-8") from error

    def read_hash_name(self) -> str:
        return self.read_text("hash_name")

    def expect_end(self, label: str) -> None:
        if self._offset != len(self._data):
            raise ValueError(f"trailing bytes after the {label}")


def _proof_level_count(index: int, size: int) -> int:
    """Sibling count an inclusion proof for ``index`` within ``size`` entries needs."""
    count = 0
    position = index
    width = size
    while width > 1:
        if position % 2 == 1 or position + 1 < width:
            count += 1
        position //= 2
        width = (width + 1) // 2
    return count


